PRAGMA foreign_keys = ON;

BEGIN TRANSACTION;

INSERT INTO core_publication
  (publication_type, pmid, authors, title, journal, publication_date, url,
   contains_promoter_data, contains_expression_data, submission_notes, curation_complete,
   reported_TF, reported_species)
SELECT
  'ARTICLE',
  '37175009',
  'Rehman SU, Khan MA, Masood A, Almujally NA, Baili J, Alhaisoni M, Tariq U, Zhang YD',
  'BRMI-Net: Deep Learning Features and Flower Pollination-Controlled Regula Falsi-Based Feature Selection Framework for Breast Cancer Recognition in Mammography Images.',
  'Diagnostics (Basel, Switzerland)',
  '2023 May 3',
  'https://doi.org/10.3390/diagnostics13091618',
  0,
  1,
  'Stress test 1',
  1,
  'LeuO',
  'Salmonella enterica subsp. enterica serovar Typhimurium str. LT2'
WHERE NOT EXISTS (
  SELECT 1 FROM core_publication WHERE pmid='37175009'
);

UPDATE core_publication
SET
  authors = CASE WHEN authors IS NULL OR authors='' THEN 'Rehman SU, Khan MA, Masood A, Almujally NA, Baili J, Alhaisoni M, Tariq U, Zhang YD' ELSE authors END,
  title = CASE WHEN title IS NULL OR title='' THEN 'BRMI-Net: Deep Learning Features and Flower Pollination-Controlled Regula Falsi-Based Feature Selection Framework for Breast Cancer Recognition in Mammography Images.' ELSE title END,
  journal = CASE WHEN journal IS NULL OR journal='' THEN 'Diagnostics (Basel, Switzerland)' ELSE journal END,
  publication_date = CASE WHEN publication_date IS NULL OR publication_date='' THEN '2023 May 3' ELSE publication_date END,
  url = CASE WHEN url IS NULL OR url='' THEN 'https://doi.org/10.3390/diagnostics13091618' ELSE url END,
  reported_TF = CASE WHEN reported_TF IS NULL OR reported_TF='' THEN 'LeuO' ELSE reported_TF END,
  reported_species = CASE WHEN reported_species IS NULL OR reported_species='' THEN 'Salmonella enterica subsp. enterica serovar Typhimurium str. LT2' ELSE reported_species END,
  contains_promoter_data = 0,
  contains_expression_data = 1,
  curation_complete = 1,
  submission_notes = CASE
    WHEN submission_notes IS NULL OR submission_notes='' THEN 'Stress test 1'
    ELSE submission_notes
  END
WHERE pmid='37175009';

INSERT INTO core_tf (name, family_id, description)
SELECT 'LeuO', 15, 'LeuO is a LysR-type global transcriptional regulator described in Escherichia coli and Salmonella typhi. LeuO has an N-terminal DNA-binding domain with a winged helix-turn-helix motif and a long linker-helix involved in dimerization that connects the DNA-binding domian with the C-terminal regulatory domain. Leu forms tetramers that that binds with high affinity to DNA [PMID::24659766]'
WHERE NOT EXISTS (
  SELECT 1 FROM core_tf WHERE lower(name)=lower('LeuO')
);

UPDATE core_tf
SET
  family_id = COALESCE(family_id, 15),
  description = CASE WHEN description IS NULL THEN 'LeuO is a LysR-type global transcriptional regulator described in Escherichia coli and Salmonella typhi. LeuO has an N-terminal DNA-binding domain with a winged helix-turn-helix motif and a long linker-helix involved in dimerization that connects the DNA-binding domian with the C-terminal regulatory domain. Leu forms tetramers that that binds with high affinity to DNA [PMID::24659766]' ELSE description END
WHERE lower(name)=lower('LeuO');

INSERT INTO core_tfinstance (refseq_accession, uniprot_accession, description, TF_id, notes)
SELECT
  'WP_000131699',
  'Q7CQY3',
  'ferric uptake regulator [Salmonella enterica subsp. enterica serovar Typhimurium str. LT2].',
  (SELECT TF_id FROM core_tf WHERE lower(name)=lower('LeuO') LIMIT 1),
  ''
WHERE NOT EXISTS (
  SELECT 1 FROM core_tfinstance WHERE uniprot_accession='Q7CQY3'
);

UPDATE core_tfinstance
SET
  TF_id = COALESCE(TF_id, (SELECT TF_id FROM core_tf WHERE lower(name)=lower('LeuO') LIMIT 1)),
  refseq_accession = COALESCE(NULLIF(refseq_accession,''), 'WP_000131699'),
  description = COALESCE(NULLIF(description,''), 'ferric uptake regulator [Salmonella enterica subsp. enterica serovar Typhimurium str. LT2].'),
  notes = COALESCE(notes, '')
WHERE uniprot_accession='Q7CQY3';

INSERT INTO core_curation
  (TF_species, site_species, experimental_process, forms_complex,
   complex_notes, notes, last_modified, curator_id, publication_id, created, validated_by_id)
VALUES
  ('Salmonella enterica subsp. enterica serovar Typhimurium str. LT2', 'Salmonella enterica subsp. enterica serovar Typhimurium str. LT2', NULL,
   0, NULL, 'Stress test 1',
   datetime('now'), (SELECT curator_id FROM core_curator ORDER BY curator_id LIMIT 1), (SELECT publication_id FROM core_publication WHERE pmid='37175009' LIMIT 1), datetime('now'), NULL);

INSERT INTO core_curation_TF_instances (curation_id, tfinstance_id)
SELECT (SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='37175009' LIMIT 1) ORDER BY curation_id DESC LIMIT 1), (SELECT TF_instance_id FROM core_tfinstance WHERE uniprot_accession='Q7CQY3' LIMIT 1)
WHERE NOT EXISTS (
  SELECT 1 FROM core_curation_TF_instances
  WHERE curation_id=(SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='37175009' LIMIT 1) ORDER BY curation_id DESC LIMIT 1) AND tfinstance_id=(SELECT TF_instance_id FROM core_tfinstance WHERE uniprot_accession='Q7CQY3' LIMIT 1)
);

